18	/// Compute the declaration hash over canonical content excluding `declaration_hash`.
19	pub fn compute_declaration_hash(decl: &SettlementDeclaration) -> Result<String, ForgeError> {
20	    let mut copy = decl.clone();
21	    copy.declaration_hash.clear();
22	    hash_canonical(&copy)
23	}
