25	/// Append a declaration to a JSONL file.
26	pub fn append_declaration(path: &Path, decl: &SettlementDeclaration) -> Result<(), ForgeError> {
27	    let mut file = OpenOptions::new()
28	        .create(true)
29	        .append(true)
30	        .open(path)
31	        .map_err(|e| ForgeError::io(format!("open {}", path.display()), e))?;
32	    let mut encoded = serde_json::to_vec(decl)?;
33	    encoded.push(b'\n');
34	    file.write_all(&encoded)
35	        .and_then(|_| file.flush())
36	        .map_err(|e| ForgeError::io("append declaration", e))
37	}
