39	/// Commit a declaration to the M0 ledger before appending its compatibility view.
40	pub fn append_declaration_ledgered(
41	    root: &Path,
42	    view_path: &Path,
43	    actor: &str,
44	    decl: &SettlementDeclaration,
45	) -> Result<(), ForgeError> {
46	    if compute_declaration_hash(decl)? != decl.declaration_hash {
47	        return Err(ForgeError::Plan {
48	            class: "settlement_integrity_error",
49	            message: "declaration_hash mismatch".into(),
50	        });
51	    }
52	    LedgerStream::open(root, format!("case-{}", decl.case_id), actor)?.commit_typed(
53	        "settlement_declaration",
54	        vec![
55	            decl.case_id.clone(),
56	            decl.settlement_ref.clone(),
57	            decl.declaration_id.clone(),
58	        ],
59	        decl,
60	        vec![decl.declarer.authority_ref.clone()],
61	    )?;
62	    append_declaration(view_path, decl)
63	}
