65	pub fn append_declaration_ledgered_once(
66	    root: &Path,
67	    view_path: &Path,
68	    actor: &str,
69	    decl: &SettlementDeclaration,
70	) -> Result<CommittedRecordRef, ForgeError> {
71	    if compute_declaration_hash(decl)? != decl.declaration_hash {
72	        return Err(ForgeError::Plan {
73	            class: "settlement_integrity_error",
74	            message: "declaration_hash mismatch".into(),
75	        });
76	    }
77	    let idempotency_key = hash_canonical(&(
78	        &decl.case_id,
79	        &decl.run_id,
80	        &decl.claim_manifest_sha256,
81	        &decl.declarer.authority_ref,
82	        &decl.settlement_ref,
83	        &decl.plan_item_id,
84	    ))?;
85	    let committed = LedgerStream::open(root, format!("case-{}", decl.case_id), actor)?
86	        .commit_typed_once(
87	            "settlement_declaration",
88	            idempotency_key,
89	            vec![decl.case_id.clone(), decl.run_id.clone()],
90	            decl,
91	            vec![decl.declarer.authority_ref.clone()],
92	        )?;
93	    append_declaration_view_once(view_path, decl)?;
94	    Ok(committed)
95	}
