97	/// Atomically check-and-append a declaration view under a file lock.
98	/// Same declaration_id with identical content is a no-op; same ID with different
99	/// content is rejected. The lock covers both read and write.
100	fn append_declaration_view_once(
101	    path: &Path,
102	    decl: &SettlementDeclaration,
103	) -> Result<(), ForgeError> {
104	    if let Some(parent) = path.parent() {
105	        std::fs::create_dir_all(parent)
106	            .map_err(|e| ForgeError::io(format!("create {}", parent.display()), e))?;
107	    }
108	    let lock_path = path.with_extension("lock");
109	    let lock_file = OpenOptions::new()
110	        .create(true)
111	        .truncate(false)
112	        .read(true)
113	        .write(true)
114	        .open(&lock_path)
115	        .map_err(|e| ForgeError::io(format!("open {}", lock_path.display()), e))?;
116	    lock_file
117	        .lock()
118	        .map_err(|e| ForgeError::io("lock declaration view", e))?;
119	    let result = (|| {
120	        let declarations = load_declarations(path)?;
121	        if let Some(existing) = declarations
122	            .iter()
123	            .find(|existing| existing.declaration_id == decl.declaration_id)
124	        {
125	            if existing.declaration_hash != decl.declaration_hash {
126	                return Err(ForgeError::Plan {
127	                    class: "settlement_integrity_error",
128	                    message: format!(
129	                        "declaration {} content conflicts with existing view entry",
130	                        decl.declaration_id
131	                    ),
132	                });
133	            }
134	            return Ok(());
135	        }
136	        append_declaration(path, decl)
137	    })();
138	    let unlock = lock_file
139	        .unlock()
140	        .map_err(|e| ForgeError::io("unlock declaration view", e));
141	    match result {
142	        Ok(()) => unlock,
143	        Err(error) => Err(error),
144	    }
145	}
