147	/// Load all declarations from a JSONL file. Returns empty vec if file does not exist.
148	pub fn load_declarations(path: &Path) -> Result<Vec<SettlementDeclaration>, ForgeError> {
149	    if !path.exists() {
150	        return Ok(Vec::new());
151	    }
152	    let file =
153	        File::open(path).map_err(|e| ForgeError::io(format!("open {}", path.display()), e))?;
154	    let mut decls = Vec::new();
155	    for line in BufReader::new(file).lines() {
156	        let line = line.map_err(|e| ForgeError::io("read declarations", e))?;
157	        if line.trim().is_empty() {
158	            continue;
159	        }
160	        let decl: SettlementDeclaration =
161	            serde_json::from_str(&line).map_err(|e| ForgeError::Serialization(e.to_string()))?;
162	        decls.push(decl);
163	    }
164	    Ok(decls)
165	}
