296	impl SweSeedTransport for CommandSweSeedTransport {
297	    fn submit(&self, req: &SettlementDeclarationRequest) -> Result<SweSeedResponse, ForgeError> {
298	        use std::os::unix::process::CommandExt;
299	
300	        let mut command = Command::new(&self.argv[0]);
301	        command
302	            .args(&self.argv[1..])
303	            .env_clear()
304	            .stdin(Stdio::piped())
305	            .stdout(Stdio::piped())
306	            .stderr(Stdio::piped());
307	        // Own process group so timeout can terminate the full tree.
308	        command.process_group(0);
309	        let mut child = command.spawn().map_err(settlement_authority_unavailable)?;
310	        let mut stdin = child
311	            .stdin
312	            .take()
313	            .ok_or_else(|| settlement_authority_unavailable("SWE_SEED stdin was not piped"))?;
314	        let request = serde_json::to_vec(req)?;
315	        let stdin_done = Arc::new(AtomicBool::new(false));
316	        let stdin_flag = Arc::clone(&stdin_done);
317	        let stdin_writer = thread::spawn(move || {
318	            let result = stdin.write_all(&request).and_then(|_| stdin.flush());
319	            stdin_flag.store(true, Ordering::SeqCst);
320	            result
321	        });
322	        let stdout = child
323	            .stdout
324	            .take()
325	            .ok_or_else(|| settlement_authority_unavailable("SWE_SEED stdout was not piped"))?;
326	        let stderr = child
327	            .stderr
328	            .take()
329	            .ok_or_else(|| settlement_authority_unavailable("SWE_SEED stderr was not piped"))?;
330	        let stdout_reader = thread::spawn(move || {
331	            let mut bytes = Vec::new();
332	            stdout
333	                .take(1_048_577)
334	                .read_to_end(&mut bytes)
335	                .map(|_| bytes)
336	        });
337	        let stderr_reader = thread::spawn(move || {
338	            let mut bytes = Vec::new();
339	            stderr.take(65_537).read_to_end(&mut bytes).map(|_| bytes)
340	        });
341	        let started = Instant::now();
342	        let deadline = started + self.timeout;
343	        let status = loop {
344	            if let Some(status) = child.try_wait().map_err(settlement_authority_unavailable)? {
345	                break status;
346	            }
347	            if Instant::now() >= deadline {
348	                terminate_process_tree(&child)?;
349	                let _ = child.wait();
350	                return Err(settlement_authority_unavailable(
351	                    "SWE_SEED command timed out",
352	                ));
353	            }
354	            thread::sleep(Duration::from_millis(10));
355	        };
356	        // Require stdin completion within remaining timeout before accepting response.
357	        while !stdin_done.load(Ordering::SeqCst) {
358	            if Instant::now() >= deadline {
359	                terminate_process_tree(&child)?;
360	                let _ = child.wait();
361	                return Err(settlement_authority_unavailable(
362	                    "SWE_SEED command timed out",
363	                ));
364	            }
365	            thread::sleep(Duration::from_millis(10));
366	        }
367	        stdin_writer
368	            .join()
369	            .map_err(|_| settlement_authority_unavailable("SWE_SEED stdin writer failed"))?
370	            .map_err(settlement_authority_unavailable)?;
371	        let stdout = join_reader_within(stdout_reader, deadline, "stdout")?;
372	        let stderr = join_reader_within(stderr_reader, deadline, "stderr")?;
373	        if !status.success() || stdout.len() > 1_048_576 || stderr.len() > 65_536 {
374	            return Err(settlement_authority_unavailable(
375	                "SWE_SEED command failed or exceeded output limits",
376	            ));
377	        }
378	        serde_json::from_slice(&stdout).map_err(|_| {
379	            settlement_authority_unavailable("SWE_SEED returned an invalid JSON response")
380	        })
381	    }
382	}
