384	fn terminate_process_tree(child: &std::process::Child) -> Result<(), ForgeError> {
385	    let group = format!("-{}", child.id());
386	    let group_kill = Command::new("/bin/kill")
387	        .args(["-KILL", "--", &group])
388	        .env_clear()
389	        .output()
390	        .map_err(settlement_authority_unavailable)?;
391	    if !group_kill.status.success() {
392	        let group_still_exists = Command::new("/bin/kill")
393	            .args(["-0", "--", &group])
394	            .env_clear()
395	            .output()
396	            .map_err(settlement_authority_unavailable)?
397	            .status
398	            .success();
399	        if group_still_exists {
400	            return Err(settlement_authority_unavailable(
401	                "SWE_SEED process group survived termination",
402	            ));
403	        }
404	    }
405	    Ok(())
406	}
