408	fn join_reader_within(
409	    handle: thread::JoinHandle<std::io::Result<Vec<u8>>>,
410	    deadline: Instant,
411	    label: &str,
412	) -> Result<Vec<u8>, ForgeError> {
413	    loop {
414	        if handle.is_finished() {
415	            return handle
416	                .join()
417	                .map_err(|_| {
418	                    settlement_authority_unavailable(format!("SWE_SEED {label} reader failed"))
419	                })?
420	                .map_err(settlement_authority_unavailable);
421	        }
422	        if Instant::now() >= deadline {
423	            return Err(settlement_authority_unavailable(
424	                "SWE_SEED command timed out",
425	            ));
426	        }
427	        thread::sleep(Duration::from_millis(10));
428	    }
429	}
