541	/// Integrity checks shared by all adapters (spec §7.2.1).
542	fn check_integrity(req: &SettlementDeclarationRequest) -> Result<(), ForgeError> {
543	    // SoD boundary (spec-adlc-thoth §10.3, T13B): the actor that authored the
544	    // claim being settled cannot itself be the declarer.
545	    sea_forge_core::types::validate_claim_authorship_sod(
546	        req.authored_by.as_deref(),
547	        &req.declarer.actor_id,
548	    )?;
549	    if req.criteria_declared_at > req.execution_started_at {
550	        return Err(ForgeError::Plan {
551	            class: "settlement_integrity_error",
552	            message: "criteria_declared_at follows execution_started_at (post-hoc criteria)".into(),
553	        });
554	    }
555	    if req.declarer.actor_id == req.acting_entity_id {
556	        return Err(ForgeError::Plan {
557	            class: "settlement_integrity_error",
558	            message: "declarer is the acting entity (self-declaration)".into(),
559	        });
560	    }
561	    if req.criteria_ref.is_empty() {
562	        return Err(ForgeError::Plan {
563	            class: "settlement_integrity_error",
564	            message: "missing criteria_ref (legacy_unattributed_criteria)".into(),
565	        });
566	    }
567	    if req.origin_refs.is_empty() {
568	        return Err(ForgeError::Plan {
569	            class: "settlement_integrity_error",
570	            message: "missing origin_refs".into(),
571	        });
572	    }
573	    Ok(())
574	}
