576	/// Fixed-point weight: attribution_confidence * (1 - gaming_exposure) * (1 - hidden_debt_blindness).
577	/// Uses i64 millionths internally, clamped to [0, 1_000_000].
578	fn compute_weight(conf: &str, exposure: &str, blindness: &str) -> String {
579	    let c = parse_fixed(conf).unwrap_or(0);
580	    let e = parse_fixed(exposure).unwrap_or(0);
581	    let b = parse_fixed(blindness).unwrap_or(0);
582	    let weight = c * (1_000_000 - e) / 1_000_000 * (1_000_000 - b) / 1_000_000;
583	    format_fixed(weight.clamp(0, 1_000_000))
584	}
585	
586	/// Parse a fixed-scale decimal string ("0.800000") into millionths (800000).
587	fn parse_fixed(s: &str) -> Result<i64, ()> {
588	    let s = s.trim();
589	    let (sign, rest) = if let Some(stripped) = s.strip_prefix('-') {
590	        (-1, stripped)
591	    } else {
592	        (1, s)
593	    };
594	    let parts: Vec<&str> = rest.split('.').collect();
595	    let int_part: i64 = parts
596	        .first()
597	        .filter(|p| !p.is_empty())
598	        .map(|p| p.parse::<i64>().unwrap_or(0))
599	        .unwrap_or(0);
600	    let frac_part = parts.get(1).unwrap_or(&"");
601	    let frac_padded = format!("{:0<6}", &frac_part[..frac_part.len().min(6)]);
602	    let frac: i64 = frac_padded.parse().unwrap_or(0);
603	    Ok(sign * (int_part * 1_000_000 + frac))
604	}
605	
606	/// Format millionths (800000) as a fixed-scale decimal string ("0.800000").
607	fn format_fixed(v: i64) -> String {
608	    let sign = if v < 0 { "-" } else { "" };
609	    let abs = v.unsigned_abs();
610	    format!("{}{}.{:06}", sign, abs / 1_000_000, abs % 1_000_000)
611	}
