613	#[cfg(test)]
614	mod tests {
615	    use super::*;
616	
617	    #[test]
618	    fn fixed_point_roundtrip() {
619	        assert_eq!(parse_fixed("0.800000").unwrap(), 800_000);
620	        assert_eq!(parse_fixed("1.000000").unwrap(), 1_000_000);
621	        assert_eq!(parse_fixed("0.000000").unwrap(), 0);
622	        assert_eq!(format_fixed(800_000), "0.800000");
623	        assert_eq!(format_fixed(1_000_000), "1.000000");
624	    }
625	
626	    #[test]
627	    fn weight_high_confidence_low_exposure() {
628	        let w = compute_weight("0.950000", "0.050000", "0.100000");
629	        let v = parse_fixed(&w).unwrap();
630	        // 0.95 * 0.95 * 0.90 = 0.812250 → 812250
631	        assert!(v >= 800_000, "expected weight >= 0.8, got {w}");
632	    }
633	
634	    #[test]
635	    fn weight_high_exposure_reduces() {
636	        let w = compute_weight("0.950000", "0.800000", "0.100000");
637	        let v = parse_fixed(&w).unwrap();
638	        // 0.95 * 0.20 * 0.90 = 0.171 → 171000
639	        assert!(v < 200_000, "expected weight < 0.2, got {w}");
640	    }
641	}
