33	fn load_ledgered_case_approvals(
34	    entries: &[LedgerEntry],
35	    plan: &CasePlan,
36	    case_id: &str,
37	) -> Result<Vec<ApprovalRequest>, ForgeError> {
38	    let integrity_error =
39	        |message: &str| ForgeError::Internal(format!("ledger_integrity_error: {message}"));
40	    let mut requests = BTreeMap::<String, ApprovalRequest>::new();
41	    let mut resolutions = BTreeMap::<String, ApprovalRequest>::new();
42	    for entry in entries {
43	        let target = match entry.record_kind.as_str() {
44	            "approval_request" => &mut requests,
45	            "approval_resolution" => &mut resolutions,
46	            _ => continue,
47	        };
48	        let approval: ApprovalRequest = serde_json::from_value(entry.payload.clone())?;
49	        if target
50	            .insert(approval.approval_id.clone(), approval)
51	            .is_some()
52	        {
53	            return Err(integrity_error("duplicate approval record"));
54	        }
55	    }
56	    if resolutions.keys().any(|id| !requests.contains_key(id)) {
57	        return Err(integrity_error("approval resolution has no request"));
58	    }
59	
60	    requests
61	        .into_values()
62	        .map(|request| {
63	            if request.case_id != case_id {
64	                return Err(integrity_error("approval request case mismatch"));
65	            }
66	            let item = plan
67	                .items
68	                .iter()
69	                .find(|item| item.plan_item_id == request.plan_item_id)
70	                .ok_or_else(|| integrity_error("approval plan item is missing"))?;
71	            if item.settlement_criteria_ref.as_deref() != request.criteria_ref.as_deref() {
72	                return Err(integrity_error(
73	                    "approval criteria does not match plan item",
74	                ));
75	            }
76	            let criteria_ref = request
77	                .criteria_ref
78	                .as_deref()
79	                .ok_or_else(|| integrity_error("approval criteria reference is missing"))?;
80	            let criteria_entries = entries
81	                .iter()
82	                .filter(|entry| {
83	                    entry.record_kind == "settlement_criteria"
84	                        && entry.payload.get("criteria_id").and_then(Value::as_str)
85	                            == Some(criteria_ref)
86	                })
87	                .collect::<Vec<_>>();
88	            if criteria_entries.len() != 1 {
89	                return Err(integrity_error("approval criteria record is not unique"));
90	            }
91	            let criteria: SettlementCriteriaRecord =
92	                serde_json::from_value(criteria_entries[0].payload.clone())?;
93	            if request.criteria_sha256.as_deref() != Some(criteria.criteria_sha256.as_str())
94	                || request.criteria_record_hash.as_deref()
95	                    != Some(criteria.criteria_record_hash.as_str())
96	            {
97	                return Err(integrity_error("approval criteria hash mismatch"));
98	            }
99	            let Some(resolution) = resolutions.remove(&request.approval_id) else {
100	                return Ok(request);
101	            };
102	            if resolution.status == ApprovalStatus::Pending
103	                || resolution.run_id != request.run_id
104	                || resolution.case_id != request.case_id
105	                || resolution.decision_id != request.decision_id
106	                || resolution.plan_item_id != request.plan_item_id
107	                || resolution.criteria_ref != request.criteria_ref
108	                || resolution.criteria_sha256 != request.criteria_sha256
109	                || resolution.criteria_record_hash != request.criteria_record_hash
110	            {
111	                return Err(integrity_error("approval resolution binding mismatch"));
112	            }
113	            Ok(resolution)
114	        })
115	        .collect()
116	}
