118	pub fn resume(options: ResumeOptions) -> Result<ResumeOutcome, ForgeError> {
119	    let root = options
120	        .root
121	        .canonicalize()
122	        .map_err(|e| ForgeError::io("canonicalize root", e))?;
123	    let case_dir = root.join("cases").join(&options.case_id);
124	    if !case_dir.exists() {
125	        return Err(ForgeError::Input(format!(
126	            "case {} not found",
127	            options.case_id
128	        )));
129	    }
130	
131	    // Load case state.
132	    let case: Case = serde_json::from_slice(
133	        &fs::read(case_dir.join("case.json")).map_err(|e| ForgeError::io("read case.json", e))?,
134	    )
135	    .map_err(|e| ForgeError::Serialization(format!("parse case.json: {e}")))?;
136	
137	    if let Some(completed) =
138	        sea_forge_artifact_ip::load_completed_transition(&root, &options.entity, &options.case_id)?
139	    {
140	        let mut case = case;
141	        case.state = CaseState::Completed;
142	        case.closed_at
143	            .get_or_insert_with(|| Utc::now().to_rfc3339());
144	        write_json(&case_dir.join("case.json"), &case)?;
145	        println!("declaration_id={}", completed.declaration.declaration_id);
146	        println!(
147	            "transition_token_id={}",
148	            completed.token.transition_token_id
149	        );
150	        return Ok(ResumeOutcome {
151	            case_id: options.case_id,
152	            state: "completed",
153	            exit_code: 0,
154	        });
155	    }
156	    if sea_forge_artifact_ip::load_transition_terminal(&root, &options.entity, &options.case_id)?
157	        .is_some()
158	    {
159	        let mut case = case;
160	        case.state = CaseState::Terminated;
161	        case.close_reason = Some("artifact_transition_terminal".into());
162	        case.closed_at
163	            .get_or_insert_with(|| Utc::now().to_rfc3339());
164	        write_json(&case_dir.join("case.json"), &case)?;
165	        return Ok(ResumeOutcome {
166	            case_id: options.case_id,
167	            state: "terminated",
168	            exit_code: 4,
169	        });
170	    }
171	    let case_stream =
172	        LedgerStream::open(&root, format!("case-{}", options.case_id), &options.entity)?;
173	    case_stream.verify()?;
174	    let case_entries = case_stream.read_entries()?;
175	    if case_entries
176	        .iter()
177	        .any(|entry| entry.record_kind == "pending_artifact_transition")
178	    {
179	        let pending = sea_forge_artifact_ip::load_pending_transition(
180	            &root,
181	            &options.entity,
182	            &options.case_id,
183	        )?;
184	        return resume_artifact_transition(options, root, case_dir, case, pending);
185	    }
186	
187	    if case.state != CaseState::AwaitingApproval {
188	        return Err(ForgeError::Input(format!(
189	            "case {} is {} — only awaiting_approval can resume",
190	            options.case_id,
191	            serde_json::to_string(&case.state)
192	                .unwrap_or_default()
193	                .trim_matches('"')
194	        )));
195	    }
196	
197	    // Load plan.
198	    let plan: CasePlan = serde_json::from_slice(
199	        &fs::read(case_dir.join("plan.json")).map_err(|e| ForgeError::io("read plan.json", e))?,
200	    )
201	    .map_err(|e| ForgeError::Serialization(format!("parse plan.json: {e}")))?;
202	
203	    // Load events.
204	    let case_events = case_dir.join("case-events.jsonl");
205	    let mut events: Vec<TraceEvent> = Vec::new();
206	    if case_events.exists() {
207	        for line in fs::read_to_string(&case_events)
208	            .map_err(|e| ForgeError::io("read case-events.jsonl", e))?
209	            .lines()
210	        {
211	            if line.trim().is_empty() {
212	                continue;
213	            }
214	            let event: TraceEvent = serde_json::from_str(line)
215	                .map_err(|e| ForgeError::Serialization(format!("parse event: {e}")))?;
216	            events.push(event);
217	        }
218	    }
219	
220	    // Check approval status.
221	    let case_approvals = load_ledgered_case_approvals(&case_entries, &plan, &options.case_id)?;
222	    let pending = case_approvals
223	        .iter()
224	        .filter(|approval| approval.status == ApprovalStatus::Pending)
225	        .count();
226	    if pending > 0 {
227	        return Err(ForgeError::Input(format!(
228	            "case {} still has {} pending approval(s)",
229	            options.case_id, pending
230	        )));
231	    }
232	
233	    // Determine the approval outcome from authoritative case-ledger records.
234	    let has_approved = case_approvals
235	        .iter()
236	        .any(|a| a.status == ApprovalStatus::Approved);
237	    let _has_expired = case_approvals
238	        .iter()
239	        .any(|a| a.status == ApprovalStatus::Expired || a.status == ApprovalStatus::Rejected);
240	
241	    if !has_approved {
242	        // If rejected or expired, terminate the case.
243	        let mut case = case;
244	        case.state = CaseState::Terminated;
245	        case.close_reason = Some("authority_escalate_expired".into());
246	        case.closed_at = Some(Utc::now().to_rfc3339());
247	        write_json(&case_dir.join("case.json"), &case)?;
248	        let stream =
249	            LedgerStream::open(&root, format!("case-{}", options.case_id), &options.entity)?;
250	        append_event(
251	            &case_events,
252	            &stream,
253	            &mut events,
254	            TraceKind::CaseTerminated,
255	            None,
256	            json!({"basis": "authority_escalate_expired"}),
257	        )?;
258	        return Ok(ResumeOutcome {
259	            case_id: options.case_id,
260	            state: "terminated",
261	            exit_code: 4,
262	        });
263	    }
264	
265	    // Approved: re-enter the case loop.
266	    let stream = LedgerStream::open(&root, format!("case-{}", options.case_id), &options.entity)?;
267	    let bundle = sea_forge_authority::AuthorityPolicyBundle::load(&options.policy)?;
268	    let engine = sea_forge_authority::PolicyAuthorityEngine::new(bundle.clone())?;
269	    let actor = Actor {
270	        actor_id: options.entity.clone(),
271	        role: ActorRole::Operator,
272	    };
273	    let binding = bundle.resolve_identity(&actor.actor_id, actor.role.clone());
274	    let runs_dir = case_dir.join("runs");
275	
276	    // Reconstruct authority for items that need to execute.
277	    // ponytail: on resume, re-evaluate authority for items that haven't completed.
278	    let mut run_ids = HashMap::<(String, u32), String>::new();
279	    let mut auth = HashMap::<(String, u32), Vec<AuthorizedOperation>>::new();
280	    for item in &plan.items {
281	        if item.item_kind != ItemKind::SandboxedTask {
282	            continue;
283	        }
284	        let projection = sea_forge_planner::case_engine::replay_case(&plan.items, &events);
285	        let existing = projection
286	            .items
287	            .iter()
288	            .find(|s| s.item_id == item.plan_item_id);
289	        let completed = existing
290	            .is_some_and(|s| s.status == sea_forge_planner::case_engine::ItemStatus::Completed);
291	        if completed {
292	            continue;
293	        }
294	        for instance in 1..=item.max_instances {
295	            let run_id = if instance == 1 {
296	                case_approvals
297	                    .iter()
298	                    .find(|approval| {
299	                        approval.status == ApprovalStatus::Approved
300	                            && approval.plan_item_id == item.plan_item_id
301	                    })
302	                    .map_or_else(ids::run_id, |approval| Ok(approval.run_id.clone()))?
303	            } else {
304	                ids::run_id()?
305	            };
306	            let workspace = runs_dir.join(&run_id).join("workspace");
307	            let artifacts = runs_dir.join(&run_id).join("artifacts");
308	            let mut operations = Vec::new();
309	            for (sequence, operation) in item.operations.iter().enumerate() {
310	                let action = AuthorityAction::from(operation);
311	                let env_keys = if matches!(operation, Operation::ExecuteCommand { .. }) {
312	                    ["PATH", "HOME"].into_iter().map(str::to_owned).collect()
313	                } else {
314	                    Default::default()
315	                };
316	                let decision = engine.evaluate(sea_forge_authority::AuthorityEvaluation {
317	                    actor: &actor,
318	                    binding: binding.clone(),
319	                    run_id: &run_id,
320	                    case_id: &options.case_id,
321	                    plan_item_id: &item.plan_item_id,
322	                    sequence: sequence + 1,
323	                    action: &action,
324	                    workspace_root: &workspace,
325	                    evidence_refs: vec![],
326	                    artifacts_root: matches!(operation, Operation::ExecuteCommand { .. })
327	                        .then_some(artifacts.as_path()),
328	                    timeout_secs: matches!(operation, Operation::ExecuteCommand { .. })
329	                        .then_some(options.timeout_secs),
330	                    env_keys,
331	                    domainforge_candidate: None,
332	                    environment: None,
333	                })?;
334	                let request = stream.commit_typed(
335	                    "authority_request",
336	                    vec![options.case_id.clone(), item.plan_item_id.clone()],
337	                    &decision.action_request,
338	                    vec![],
339	                )?;
340	                let committed = stream.commit_typed(
341	                    "authority_decision",
342	                    vec![options.case_id.clone(), item.plan_item_id.clone()],
343	                    &decision,
344	                    vec![request.entry_ulid().into()],
345	                )?;
346	                operations.push(AuthorizedOperation {
347	                    decision,
348	                    committed,
349	                });
350	            }
351	            run_ids.insert((item.plan_item_id.clone(), instance), run_id);
352	            auth.insert((item.plan_item_id.clone(), instance), operations);
353	        }
354	    }
355	
356	    // Continue the case loop.
357	    let mut case = case;
358	    case.state = CaseState::Active;
359	    write_json(&case_dir.join("case.json"), &case)?;
360	    loop {
361	        let actions = sea_forge_planner::case_engine::next_case_actions(&plan.items, &events);
362	        if actions.is_empty() {
363	            write_json(&case_dir.join("case.json"), &case)?;
364	            return Ok(ResumeOutcome {
365	                case_id: options.case_id,
366	                state: "active",
367	                exit_code: 5,
368	            });
369	        }
370	        for action in actions {
371	            match action {
372	                sea_forge_planner::case_engine::CaseAction::Enable(item_id) => {
373	                    append_event(
374	                        &case_events,
375	                        &stream,
376	                        &mut events,
377	                        TraceKind::ItemEnabled,
378	                        Some(&item_id),
379	                        json!({}),
380	                    )?;
381	                }
382	                sea_forge_planner::case_engine::CaseAction::ParkHumanTask(item_id) => {
383	                    append_event(
384	                        &case_events,
385	                        &stream,
386	                        &mut events,
387	                        TraceKind::ItemActivated,
388	                        Some(&item_id),
389	                        json!({"human_task": true}),
390	                    )?;
391	                    write_json(&case_dir.join("case.json"), &case)?;
392	                    return Ok(ResumeOutcome {
393	                        case_id: options.case_id,
394	                        state: "active",
395	                        exit_code: 5,
396	                    });
397	                }
398	                sea_forge_planner::case_engine::CaseAction::AchieveMilestone(item_id) => {
399	                    append_event(
400	                        &case_events,
401	                        &stream,
402	                        &mut events,
403	                        TraceKind::MilestoneAchieved,
404	                        Some(&item_id),
405	                        json!({}),
406	                    )?;
407	                }
408	                sea_forge_planner::case_engine::CaseAction::Activate(item_id) => {
409	                    let projection =
410	                        sea_forge_planner::case_engine::replay_case(&plan.items, &events);
411	                    let instance = projection
412	                        .items
413	                        .iter()
414	                        .find(|state| state.item_id == item_id)
415	                        .map_or(1, |state| state.instances + 1);
416	                    append_event(
417	                        &case_events,
418	                        &stream,
419	                        &mut events,
420	                        TraceKind::ItemActivated,
421	                        Some(&item_id),
422	                        json!({"instance": instance}),
423	                    )?;
424	                    let run_id = run_ids
425	                        .get(&(item_id.clone(), instance))
426	                        .cloned()
427	                        .ok_or_else(|| ForgeError::Internal("missing allocated episode".into()))?;
428	                    let run_dir = runs_dir.join(&run_id);
429	                    let workspace = run_dir.join("workspace");
430	                    let artifacts = run_dir.join("artifacts");
431	                    fs::create_dir_all(&workspace)
432	                        .and_then(|_| fs::create_dir_all(&artifacts))
433	                        .map_err(|error| ForgeError::io("create episode directories", error))?;
434	                    let item = plan
435	                        .items
436	                        .iter()
437	                        .find(|item| item.plan_item_id == item_id)
438	                        .ok_or_else(|| ForgeError::Internal("missing plan item".into()))?;
439	                    let authorized = auth
440	                        .get(&(item_id.clone(), instance))
441	                        .ok_or_else(|| ForgeError::Internal("missing episode authority".into()))?;
442	                    let mut execution = None;
443	                    let allowed = authorized
444	                        .iter()
445	                        .all(|operation| operation.decision.verdict == Verdict::Allow);
446	                    if allowed {
447	                        for (index, operation) in item.operations.iter().enumerate() {
448	                            let granted = &authorized[index];
449	                            if matches!(operation, Operation::AgentProbe { .. }) {
450	                                return Err(ForgeError::Input(
451	                                    "agent_probe must be dispatched by sea-forge-server".into(),
452	                                ));
453	                            }
454	                            let grant = engine.grant(
455	                                &granted.decision,
456	                                &granted.committed,
457	                                &AuthorityAction::from(operation),
458	                                None,
459	                            )?;
460	                            match operation {
461	                                Operation::WriteFile { .. } => sea_forge_sandbox::materialize(
462	                                    grant,
463	                                    &workspace,
464	                                    &run_id,
465	                                    &item_id,
466	                                    operation,
467	                                    &granted.decision.compensating_controls,
468	                                )?,
469	                                Operation::ExecuteCommand { .. } => {
470	                                    let mut env = BTreeMap::new();
471	                                    if let Ok(value) = std::env::var("PATH") {
472	                                        env.insert("PATH".into(), value);
473	                                    }
474	                                    if let Ok(value) = std::env::var("HOME") {
475	                                        env.insert("HOME".into(), value);
476	                                    }
477	                                    execution = Some(sea_forge_runtime::execute(
478	                                        grant,
479	                                        &ExecutionRequest {
480	                                            plan_item_id: item_id.clone(),
481	                                            operation: operation.clone(),
482	                                            timeout_secs: options.timeout_secs,
483	                                            env,
484	                                            compensating_controls: granted
485	                                                .decision
486	                                                .compensating_controls
487	                                                .clone(),
488	                                        },
489	                                        &run_id,
490	                                        &workspace,
491	                                        &artifacts,
492	                                    )?);
493	                                }
494	                                Operation::AgentProbe { .. } => {
495	                                    unreachable!("agent_probe is rejected before execution")
496	                                }
497	                                Operation::AgentTask { .. } => {
498	                                    unreachable!("agent_task is rejected before execution")
499	                                }
500	                            }
501	                        }
502	                    }
503	                    if execution.is_none() && allowed {
504	                        execution = Some(ExecutionResult {
505	                            status: ExecutionStatus::Completed,
506	                            exit_code: Some(0),
507	                            stdout_path: "artifacts/stdout.txt".into(),
508	                            stderr_path: "artifacts/stderr.txt".into(),
509	                            started_at: Utc::now().to_rfc3339(),
510	                            finished_at: Utc::now().to_rfc3339(),
511	                        });
512	                        fs::write(artifacts.join("stdout.txt"), b"")
513	                            .map_err(|error| ForgeError::io("write stdout", error))?;
514	                        fs::write(artifacts.join("stderr.txt"), b"")
515	                            .map_err(|error| ForgeError::io("write stderr", error))?;
516	                    }
517	                    let settlement = sea_forge_settlement::settle(
518	                        &SettlementClaim {
519	                            run_id: run_id.clone(),
520	                            plan_item_id: item_id.clone(),
521	                            criteria_ref: item.settlement_criteria_ref.clone(),
522	                            criteria: item.settlement_criteria.clone(),
523	                            execution,
524	                            authority_verdicts: authorized
525	                                .iter()
526	                                .map(|operation| operation.decision.verdict.clone())
527	                                .collect(),
528	                            evaluator_scores: BTreeMap::new(),
529	                            batch: None,
530	                        },
531	                        &workspace,
532	                        &run_dir,
533	                    )?;
534	                    write_json(&run_dir.join("plan.json"), &plan)?;
535	                    write_json(
536	                        &run_dir.join("authority.json"),
537	                        &authorized
538	                            .iter()
539	                            .map(|operation| &operation.decision)
540	                            .collect::<Vec<_>>(),
541	                    )?;
542	                    write_json(&run_dir.join("settlement.json"), &settlement)?;
543	                    if !case.run_ids.contains(&run_id) {
544	                        case.run_ids.push(run_id.clone());
545	                    }
546	                    let accepted = settlement.status == SettlementStatus::Accepted;
547	                    append_event(
548	                        &case_events,
549	                        &stream,
550	                        &mut events,
551	                        if accepted {
552	                            TraceKind::ItemCompleted
553	                        } else {
554	                            TraceKind::ItemFailed
555	                        },
556	                        Some(&item_id),
557	                        json!({"instance": instance, "settlement": settlement.status}),
558	                    )?;
559	                    if accepted {
560	                        append_event(
561	                            &case_events,
562	                            &stream,
563	                            &mut events,
564	                            TraceKind::MilestoneAchieved,
565	                            Some(&item_id),
566	                            json!({"instance": instance}),
567	                        )?;
568	                    }
569	                    write_json(&case_dir.join("case.json"), &case)?;
570	                }
571	                sea_forge_planner::case_engine::CaseAction::CompleteCase => {
572	                    case.state = CaseState::Completed;
573	                    case.closed_at = Some(Utc::now().to_rfc3339());
574	                    append_event(
575	                        &case_events,
576	                        &stream,
577	                        &mut events,
578	                        TraceKind::CaseClosed,
579	                        None,
580	                        json!({}),
581	                    )?;
582	                    write_json(&case_dir.join("case.json"), &case)?;
583	                    return Ok(ResumeOutcome {
584	                        case_id: options.case_id,
585	                        state: "completed",
586	                        exit_code: 0,
587	                    });
588	                }
589	                sea_forge_planner::case_engine::CaseAction::TerminateCase { blocking_item } => {
590	                    case.state = CaseState::Terminated;
591	                    case.close_reason = Some(format!("required_item_failed:{blocking_item}"));
592	                    case.closed_at = Some(Utc::now().to_rfc3339());
593	                    append_event(
594	                        &case_events,
595	                        &stream,
596	                        &mut events,
597	                        TraceKind::CaseTerminated,
598	                        None,
599	                        json!({"blocking_item": blocking_item}),
600	                    )?;
601	                    write_json(&case_dir.join("case.json"), &case)?;
602	                    return Ok(ResumeOutcome {
603	                        case_id: options.case_id,
604	                        state: "terminated",
605	                        exit_code: 3,
606	                    });
607	                }
608	            }
609	        }
610	    }
611	}
