621	    stream.verify()?;
622	    let mut entries = stream.read_entries()?;
623	    let mut resolutions = entries
624	        .iter()
625	        .filter(|entry| {
626	            entry.record_kind == "approval_resolution"
627	                && entry.payload.get("approval_id").and_then(Value::as_str)
628	                    == Some(pending.approval_ref.as_str())
629	        })
630	        .collect::<Vec<_>>();
631	    if resolutions.is_empty() {
632	        let request_entry = unique_entry(
633	            &entries,
634	            "approval_request",
635	            "approval_id",
636	            &pending.approval_ref,
637	        )?;
638	        let request: ApprovalRequest = serde_json::from_value(request_entry.payload.clone())?;
639	        approval_binds_pending(&request, &pending)?;
640	        let expires_at = chrono::DateTime::parse_from_rfc3339(&request.expires_at)
641	            .map_err(|_| ForgeError::Input("approval expiry is invalid".into()))?
642	            .with_timezone(&Utc);
643	        if request.status != ApprovalStatus::Pending || Utc::now() < expires_at {
644	            return Ok(ResumeOutcome {
645	                case_id: options.case_id,
646	                state: "awaiting_approval",
647	                exit_code: 5,
648	            });
649	        }
650	        let expired = ApprovalRequest {
651	            status: ApprovalStatus::Expired,
652	            resolved_by: None,
653	            resolved_at: Some(Utc::now().to_rfc3339()),
654	            note: Some("ttl_expired".into()),
655	            ..request
656	        };
657	        stream.commit_typed_once(
658	            "approval_resolution",
659	            &expired.approval_id,
660	            vec![pending.case_id.clone(), expired.approval_id.clone()],
661	            &expired,
662	            vec![expired.decision_id.clone()],
663	        )?;
664	        approvals::append(&root, &expired)?;
665	        entries = stream.read_entries()?;
666	        resolutions = entries
667	            .iter()
668	            .filter(|entry| {
669	                entry.record_kind == "approval_resolution"
670	                    && entry.payload.get("approval_id").and_then(Value::as_str)
671	                        == Some(pending.approval_ref.as_str())
672	            })
673	            .collect();
674	    }
675	    if resolutions.len() != 1 {
676	        return Err(ForgeError::Internal(
677	            "ledger_integrity_error: conflicting approval resolutions".into(),
678	        ));
679	    }
680	    let resolution_entry = resolutions[0];
681	    let approval: ApprovalRequest = serde_json::from_value(resolution_entry.payload.clone())?;
682	    // Resume validates exact approval binding for ALL statuses before
683	    // terminalizing: a detached rejected/expired resolution from another
684	    // transition cannot affect this pending one.
