1064	fn approval_binds_pending(
1065	    approval: &ApprovalRequest,
1066	    pending: &sea_forge_artifact_ip::PendingArtifactTransition,
1067	) -> Result<(), ForgeError> {
1068	    if approval.case_id != pending.case_id
1069	        || approval.run_id != pending.run_id
1070	        || approval.decision_id != pending.authority_decision_ref
1071	        || approval.plan_item_id != pending.plan_item_id
1072	        || approval.approval_id != pending.approval_ref
1073	        || approval.criteria_ref.as_deref() != Some(pending.criteria_ref.as_str())
1074	        || approval.criteria_sha256.as_deref() != Some(pending.criteria_sha256.as_str())
1075	        || approval.criteria_record_hash.as_deref() != Some(pending.criteria_record_hash.as_str())
1076	    {
1077	        return Err(ForgeError::Input(format!(
1078	            "approval resolution {} does not bind to pending transition {}",
1079	            approval.approval_id, pending.pending_key
1080	        )));
1081	    }
1082	    Ok(())
