46	/// Scripted ACP child used by the portable M16 tests. The parent process
47	/// launches this same test binary with `--exact acp_fixture_child --nocapture`.
48	#[test]
49	fn acp_fixture_child() {
50	    if std::env::var("SEA_ACP_FIXTURE").as_deref() != Ok("1") {
51	        return;
52	    }
53	    assert!(std::env::var_os("HOME").is_none(), "parent HOME leaked");
54	    assert!(
55	        std::env::current_dir()
56	            .unwrap()
57	            .ends_with(Path::new("workspace")),
58	        "ACP child cwd is not the run workspace"
59	    );
60	
61	    let mode = std::env::var("FIXTURE_MODE").unwrap_or_else(|_| "normal".into());
62	    let tool_kind = std::env::var("FIXTURE_TOOL_KIND").unwrap_or_else(|_| "read".into());
63	    let session_id = "sess-portable-m16";
64	    let mut prompt_id = None;
65	    let stdin = std::io::stdin();
66	    for line in stdin.lock().lines() {
67	        let line = line.unwrap();
68	        let Ok(message) = serde_json::from_str::<Value>(&line) else {
69	            continue;
70	        };
71	        let id = message.get("id").and_then(Value::as_u64);
72	        match message.get("method").and_then(Value::as_str) {
73	            Some("initialize") => write_rpc(json!({
74	                "jsonrpc": "2.0",
75	                "id": id,
76	                "result": {
77	                    "protocolVersion": if mode == "protocol_bad" { 999 } else { 1 },
78	                    "agentCapabilities": {"loadSession": true}
79	                }
80	            })),
81	            Some("session/new") => {
82	                let declared = message["params"]["cwd"].as_str().unwrap_or_default();
83	                assert!(declared.ends_with("workspace"), "session/new cwd drifted");
84	                assert!(message["params"]["mcpServers"].is_array());
85	                write_rpc(json!({
86	                    "jsonrpc": "2.0",
87	                    "id": id,
88	                    "result": {"sessionId": session_id}
89	                }));
90	            }
91	            Some("session/load") => {
92	                assert_eq!(message["params"]["sessionId"], session_id);
93	                let declared = message["params"]["cwd"].as_str().unwrap_or_default();
94	                assert!(declared.ends_with("workspace"), "session/load cwd drifted");
95	                assert!(message["params"]["mcpServers"].is_array());
96	                write_rpc(json!({
97	                    "jsonrpc": "2.0",
98	                    "id": id,
99	                    "result": {}
100	                }));
101	            }
102	            Some("session/prompt") => {
103	                prompt_id = id;
104	                assert!(message["params"]["prompt"].is_array());
105	                if mode.contains("jail") {
106	                    let escaped = std::env::temp_dir()
107	                        .join(format!("sea-forge-acp-escape-{}", std::process::id()));
108	                    assert!(
109	                        std::fs::write(&escaped, "forbidden").is_err(),
110	                        "jail permitted ACP child write outside run workspace"
111	                    );
112	                    std::fs::write("jail-proof.txt", "inside-workspace").unwrap();
113	                }
114	                if mode == "disconnect" {
115	                    write_rpc(json!({
116	                        "jsonrpc": "2.0",
117	                        "method": "session/update",
118	                        "params": {
119	                            "sessionId": session_id,
120	                            "update": {
121	                                "sessionUpdate": "agent_message_chunk",
122	                                "content": {"type": "text", "text": "partial"}
123	                            }
124	                        }
125	                    }));
126	                    return;
127	                }
128	                if mode == "secret" {
129	                    // Emit a chunk carrying full plaintext sentinels so the ACP
130	                    // transcript path must redact them before hashing/storage.
131	                    finish_prompt(
132	                        prompt_id.unwrap(),
133	                        session_id,
134	                        "leaking password=hunter2 and API_KEY=sk-live-abc123 done", // gitleaks:allow
135	                    );
136	                    continue;
137	                }
138	                write_rpc(json!({
139	                    "jsonrpc": "2.0",
140	                    "method": "session/update",
141	                    "params": {
142	                        "sessionId": session_id,
143	                        "update": {
144	                            "sessionUpdate": "tool_call",
145	                            "toolCallId": "tool-1",
146	                            "title": "portable tool",
147	                            "kind": tool_kind,
148	                            "status": "pending",
149	                            "rawInput": {"path": "/tmp/portable"}
150	                        }
151	                    }
152	                }));
153	                write_rpc(json!({
154	                    "jsonrpc": "2.0",
155	                    "id": 900,
156	                    "method": "session/request_permission",
157	                    "params": {
158	                        "sessionId": session_id,
159	                        "toolCall": {"toolCallId": "tool-1"},
160	                        "options": [
161	                            {"optionId": "allow-1", "kind": "allow_once"},
162	                            {"optionId": "deny-1", "kind": "reject_once"}
163	                        ]
164	                    }
165	                }));
166	            }
167	            None if id == Some(900) => {
168	                if mode.contains("escalate") {
169	                    write_rpc(json!({
170	                        "jsonrpc": "2.0",
171	                        "id": 901,
172	                        "method": "session/set_mode",
173	                        "params": {"sessionId": session_id, "modeId": "unrestricted"}
174	                    }));
175	                } else {
176	                    if mode.starts_with("swe_seed") {
177	                        std::fs::create_dir_all(".agent-harness/proofs").unwrap();
178	                        std::fs::write(".agent-harness/route.json", br#"{"route":"portable"}"#)
179	                            .unwrap();
180	                        std::fs::write(
181	                            ".agent-harness/proofs/completed.json",
182	                            br#"{"event":"ProofCompleted"}"#,
183	                        )
184	                        .unwrap();
185	                    }
186	                    finish_prompt(prompt_id.unwrap(), session_id, "done");
187	                }
188	            }
189	            None if id == Some(901) => {
190	                assert!(message.get("error").is_some(), "escalation was not refused");
191	                finish_prompt(prompt_id.unwrap(), session_id, "done");
192	            }
193	            _ => {}
194	        }
195	    }
196	}
