592	/// Sentinel-aware transcript redaction on the ACP path: plaintext secrets in
593	/// agent output must be absent from the stored transcript artifact, its hash's
594	/// source bytes, the committed evidence records, and the settlement result.
595	/// This is the ACP analogue of the HTTP redaction guarantee — both flow through
596	/// the same `produce_transcript` choke point.
597	#[tokio::test]
598	async fn t16_7_acp_transcript_redaction_scrubs_sentinels_before_hash_and_storage() {
599	    let root = tempfile::tempdir().unwrap();
600	    write_policy(root.path(), true);
601	    let config = server_config(root.path(), "read", "secret");
602	    let case = case_id().unwrap();
603	    let (run, result) = execute_fixture(&config, &case).await;
604	    assert_eq!(result.settlement, SettlementStatus::Accepted, "{result:?}");
605	
606	    // The stored artifact (the exact bytes the digest commits to) is clean.
607	    let sha = result.transcript_sha256.as_deref().unwrap();
608	    let artifact = std::fs::read_to_string(root.path().join("runs").join(&run).join(format!(
609	        "transcript-{}.jsonl",
610	        sha.trim_start_matches("sha256:")
611	    )))
612	    .unwrap();
613	    let lower = artifact.to_lowercase();
614	    assert!(
615	        !lower.contains("password") && !lower.contains("api_key"),
616	        "sentinel leaked in transcript artifact: {artifact}"
617	    );
618	    // Re-hashing the stored bytes reproduces the committed digest exactly.
619	    let rehash = format!(
620	        "sha256:{:x}",
621	        <sha2::Sha256 as sha2::Digest>::digest(artifact.as_bytes())
622	    );
623	    assert_eq!(rehash, sha, "stored artifact bytes diverge from digest");
624	
625	    // Committed evidence/summary records carry no sentinel either.
626	    let records = entries(root.path(), &case);
627	    for entry in &records {
628	        let payload = entry.payload.to_string().to_lowercase();
629	        assert!(
630	            !payload.contains("password") && !payload.contains("api_key"),
631	            "sentinel leaked in {} payload",
632	            entry.record_kind
633	        );
634	    }
635	    assert!(records
636	        .iter()
637	        .any(|e| e.record_kind == "agent_task_evidence"));
638	}
