94	impl ServerState {
95	    pub fn new(config: ServerConfig) -> Result<Self, ForgeError> {
96	        recover_cancelled_delegations(&config)?;
97	        let max = config.max_concurrent_runs.max(1);
98	        Ok(Self {
99	            config,
100	            cases: Mutex::new(HashMap::new()),
101	            delegations: Mutex::new(HashMap::new()),
102	            permission_broker: delegation::AcpApprovalBroker::default(),
103	            semaphore: Arc::new(Semaphore::new(max)),
104	        })
105	    }
