107	    /// Reload config defensively between dispatches (§8.4).
108	    pub fn reload_config(&self) -> Result<ServerConfig, String> {
109	        match ServerConfig::load(&self.config.root.join("server.yaml")) {
110	            Ok(new_config) => Ok(new_config),
111	            Err(e) => Err(e),
112	        }
113	    }
114	
115	    pub(crate) async fn begin_planned_delegation(
116	        &self,
117	        case_id: String,
118	        run_id: String,
119	    ) -> Result<Arc<AtomicBool>, ForgeError> {
120	        let cancel = Arc::new(AtomicBool::new(false));
121	        let handle = DelegationHandle {
122	            case_id,
123	            cancel: Arc::clone(&cancel),
124	            requested: Arc::new(AtomicBool::new(false)),
125	        };
126	        if self
127	            .delegations
128	            .lock()
129	            .await
130	            .insert(run_id, handle)
131	            .is_some()
132	        {
133	            return Err(ForgeError::Input("delegation run_id already active".into()));
134	        }
135	        Ok(cancel)
136	    }
137	
138	    pub(crate) async fn end_delegation(&self, run_id: &str) {
139	        self.delegations.lock().await.remove(run_id);
140	    }
141	}
