143	/// Recover a cancellation whose control record committed before server loss.
144	/// HTTP delegations are never resumed: recovery writes the sole terminal
145	/// rejected/cancelled outcome from ledger truth.
146	fn recover_cancelled_delegations(config: &ServerConfig) -> Result<(), ForgeError> {
147	    let ledgers = config.root.join("ledgers");
148	    if !ledgers.exists() {
149	        return Ok(());
150	    }
151	    for dir in std::fs::read_dir(&ledgers).map_err(|e| ForgeError::io("read ledgers", e))? {
152	        let dir = dir.map_err(|e| ForgeError::io("read ledger entry", e))?;
153	        let name = dir.file_name().to_string_lossy().into_owned();
154	        if !dir
155	            .file_type()
156	            .map_err(|e| ForgeError::io("read ledger entry type", e))?
157	            .is_dir()
158	            || !name.starts_with("case-")
159	        {
160	            continue;
161	        }
162	        let ledger = LedgerStream::open(&config.root, &name, "sea-forge-server")?;
163	        ledger.verify()?;
164	        let entries = ledger.read_entries()?;
165	        let mut terminal_runs: std::collections::HashSet<String> = entries
166	            .iter()
167	            .filter(|entry| entry.record_kind == "settlement")
168	            .filter_map(|entry| entry.payload["run_id"].as_str().map(str::to_owned))
169	            .collect();
170	        for control in entries
171	            .iter()
172	            .filter(|entry| entry.record_kind == "control_request")
173	        {
174	            let run = control
175	                .payload
176	                .get("run_id")
177	                .and_then(serde_json::Value::as_str)
178	                .ok_or_else(|| ForgeError::Input("invalid cancellation control run_id".into()))?;
179	            if terminal_runs.contains(run) {
180	                continue;
181	            }
182	            let item_id = control
183	                .payload
184	                .get("plan_item_id")
185	                .and_then(serde_json::Value::as_str)
186	                .ok_or_else(|| {
187	                    ForgeError::Input("invalid cancellation control plan_item_id".into())
188	                })?;
189	            let case_id = control
190	                .payload
191	                .get("case_id")
192	                .and_then(serde_json::Value::as_str)
193	                .ok_or_else(|| ForgeError::Input("invalid cancellation control case_id".into()))?;
194	            let plan_path = config.root.join("runs").join(run).join("plan.json");
195	            let plan: CasePlan = serde_json::from_slice(
196	                &std::fs::read(&plan_path)
197	                    .map_err(|e| ForgeError::io("read cancelled delegation plan", e))?,
198	            )?;
199	            if plan.case_id != case_id || plan.run_id != run {
200	                return Err(ForgeError::Input(
201	                    "cancelled delegation control does not match plan identity".into(),
202	                ));
203	            }
204	            let endpoint_ref = plan
205	                .items
206	                .iter()
207	                .find(|item| item.plan_item_id == item_id)
208	                .and_then(|item| item.operations.first())
209	                .and_then(|operation| match operation {
210	                    sea_forge_core::types::Operation::AgentTask { endpoint_ref, .. } => {
211	                        Some(endpoint_ref.as_str())
212	                    }
213	                    _ => None,
214	                })
215	                .ok_or_else(|| {
216	                    ForgeError::Input("cancelled delegation plan missing agent_task".into())
217	                })?;
218	            let evidence = TranscriptEvidence {
219	                run_id: run.into(),
220	                endpoint_ref: endpoint_ref.into(),
221	                turns_used: 0,
222	                termination: DelegationTermination::Cancelled,
223	                transcript_sha256: sea_forge_agent::transcript_sha256(&[]),
224	                summary: TranscriptSummary {
225	                    turn_count: 0,
226	                    tool_calls: 0,
227	                    final_excerpt: String::new(),
228	                },
229	                artifact_ref: None,
230	                harvested_refs: vec![],
231	            };
232	            let evidence_ref = agent_probe::commit_view(
233	                &ledger,
234	                "agent_task_evidence",
235	                vec![case_id.into(), run.into(), item_id.into()],
236	                &RecoveredDelegationEvidence {
237	                    evidence: &evidence,
238	                    case_id,
239	                    item_id,
240	                },
241	                &config
242	                    .root
243	                    .join("runs")
244	                    .join(run)
245	                    .join("transcript-evidence.json"),
246	                vec![control.entry_ulid.clone()],
247	            )?;
248	            let settlement = SettlementEvent {
249	                version: "0.2".into(),
250	                settlement_id: random_id("set")?,
251	                run_id: run.into(),
252	                status: SettlementStatus::Rejected,
253	                basis: vec!["cancelled".into()],
254	                review_required: false,
255	                settled_at: Utc::now().to_rfc3339(),
256	                criteria_ref: None,
257	            };
258	            agent_probe::commit_view(
259	                &ledger,
260	                "settlement",
261	                vec![case_id.into(), run.into(), item_id.into()],
262	                &RecoveredDelegationSettlement {
263	                    settlement: &settlement,
264	                    case_id,
265	                    item_id,
266	                },
267	                &config.root.join("runs").join(run).join("settlement.json"),
268	                vec![evidence_ref.entry_ulid().into()],
269	            )?;
270	            terminal_runs.insert(run.into());
271	        }
272	
273	        for permission in entries
274	            .iter()
275	            .filter(|entry| entry.record_kind == "permission_request")
276	        {
277	            let run = permission.payload["run_id"]
278	                .as_str()
279	                .ok_or_else(|| ForgeError::Input("invalid ACP permission run_id".into()))?;
280	            if terminal_runs.contains(run) {
281	                continue;
282	            }
283	            let case_id = permission.payload["case_id"]
284	                .as_str()
285	                .ok_or_else(|| ForgeError::Input("invalid ACP permission case_id".into()))?;
286	            let item_id = permission.payload["plan_item_id"]
287	                .as_str()
288	                .ok_or_else(|| ForgeError::Input("invalid ACP permission item_id".into()))?;
289	            let continuation_key = permission.payload["session_id"]
290	                .as_str()
291	                .ok_or_else(|| ForgeError::Input("invalid ACP permission session_id".into()))?;
292	            let plan_path = config.root.join("runs").join(run).join("plan.json");
293	            let plan: CasePlan = serde_json::from_slice(
294	                &std::fs::read(&plan_path)
295	                    .map_err(|error| ForgeError::io("read orphaned ACP plan", error))?,
296	            )?;
297	            if plan.case_id != case_id || plan.run_id != run {
298	                return Err(ForgeError::Input(
299	                    "orphaned ACP permission does not match plan identity".into(),
300	                ));
301	            }
302	            let endpoint_ref = plan
303	                .items
304	                .iter()
305	                .find(|item| item.plan_item_id == item_id)
306	                .and_then(|item| item.operations.first())
307	                .and_then(|operation| match operation {
308	                    sea_forge_core::types::Operation::AgentTask { endpoint_ref, .. } => {
309	                        Some(endpoint_ref.as_str())
310	                    }
311	                    _ => None,
312	                })
313	                .ok_or_else(|| ForgeError::Input("orphaned ACP plan missing agent task".into()))?;
314	            let session_ref = agent_probe::commit_view(
315	                &ledger,
316	                "acp_session",
317	                vec![case_id.into(), run.into(), item_id.into()],
318	                &RecoveredAcpSession {
319	                    version: "0.2",
320	                    case_id,
321	                    run_id: run,
322	                    plan_item_id: item_id,
323	                    endpoint_ref,
324	                    continuation_key,
325	                    protocol_version: sea_forge_agent::ACP_PROTOCOL_VERSION,
326	                },
327	                &config.root.join("runs").join(run).join("acp-session.json"),
328	                vec![permission.entry_ulid.clone()],
329	            )?;
330	            let evidence = TranscriptEvidence {
331	                run_id: run.into(),
332	                endpoint_ref: endpoint_ref.into(),
333	                turns_used: 0,
334	                termination: DelegationTermination::AcpDisconnect,
335	                transcript_sha256: sea_forge_agent::transcript_sha256(&[]),
336	                summary: TranscriptSummary {
337	                    turn_count: 0,
338	                    tool_calls: 0,
339	                    final_excerpt: String::new(),
340	                },
341	                artifact_ref: None,
342	                harvested_refs: vec![],
343	            };
344	            let evidence_ref = agent_probe::commit_view(
345	                &ledger,
346	                "agent_task_evidence",
347	                vec![case_id.into(), run.into(), item_id.into()],
348	                &RecoveredDelegationEvidence {
349	                    evidence: &evidence,
350	                    case_id,
351	                    item_id,
352	                },
353	                &config
354	                    .root
355	                    .join("runs")
356	                    .join(run)
357	                    .join("transcript-evidence.json"),
358	                vec![
359	                    permission.entry_ulid.clone(),
360	                    session_ref.entry_ulid().into(),
361	                ],
362	            )?;
363	            let settlement = SettlementEvent {
364	                version: "0.2".into(),
365	                settlement_id: random_id("set")?,
366	                run_id: run.into(),
367	                status: SettlementStatus::Rejected,
368	                basis: vec!["acp_disconnect".into()],
369	                review_required: false,
370	                settled_at: Utc::now().to_rfc3339(),
371	                criteria_ref: None,
372	            };
373	            agent_probe::commit_view(
374	                &ledger,
375	                "settlement",
376	                vec![case_id.into(), run.into(), item_id.into()],
377	                &RecoveredDelegationSettlement {
378	                    settlement: &settlement,
379	                    case_id,
380	                    item_id,
381	                },
382	                &config.root.join("runs").join(run).join("settlement.json"),
383	                vec![evidence_ref.entry_ulid().into()],
384	            )?;
385	            terminal_runs.insert(run.into());
386	        }
387	    }
388	    Ok(())
389	}
