510	/// Start the server.
511	pub async fn run(config: ServerConfig) -> Result<(), Box<dyn std::error::Error>> {
512	    let socket_path = config.socket_path.clone();
513	    let state = Arc::new(ServerState::new(config)?);
514	
515	    // Remove stale socket.
516	    let _ = std::fs::remove_file(&socket_path);
517	
518	    let listener = UnixListener::bind(&socket_path)?;
519	
520	    // Set socket permissions to 0600 (§11.1).
521	    #[cfg(unix)]
522	    {
523	        use std::os::unix::fs::PermissionsExt;
524	        std::fs::set_permissions(&socket_path, std::fs::Permissions::from_mode(0o600))?;
525	    }
526	
527	    tracing::info!("server listening on {}", socket_path.display());
528	
529	    loop {
530	        let (stream, _) = listener.accept().await?;
531	        let state = Arc::clone(&state);
532	        tokio::spawn(async move {
533	            if let Err(e) = handle_connection(stream, state).await {
534	                tracing::warn!("connection error: {e}");
535	            }
536	        });
537	    }
538	}
539	
540	async fn handle_connection(
541	    stream: UnixStream,
542	    state: Arc<ServerState>,
543	) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
544	    let (reader, mut writer) = stream.into_split();
545	    let mut reader = BufReader::new(reader);
546	    let mut line = String::new();
547	
548	    loop {
549	        line.clear();
550	        let n = reader.read_line(&mut line).await?;
551	        if n == 0 {
552	            break;
553	        }
554	        let request: Request = match serde_json::from_str(line.trim()) {
555	            Ok(r) => r,
556	            Err(e) => {
557	                let resp = serde_json::json!({"error": format!("bad request: {e}")});
558	                writer.write_all(format!("{resp}\n").as_bytes()).await?;
559	                continue;
560	            }
561	        };
562	        let response = handle_request(request, &state).await;
563	        writer.write_all(format!("{response}\n").as_bytes()).await?;
564	    }
565	    Ok(())
566	}
