568	pub async fn handle_request(request: Request, state: &Arc<ServerState>) -> serde_json::Value {
569	    match request {
570	        Request::Submit { payload } => {
571	            // Reload config defensively (§8.4).
572	            if let Ok(new_config) = state.reload_config() {
573	                tracing::info!("config reloaded successfully");
574	                let _ = new_config;
575	            } else {
576	                tracing::warn!("invalid config reload — keeping last-known-good");
577	            }
578	
579	            match case_dispatch::submit(payload, state).await {
580	                Ok(output) => {
581	                    let case_id = output.case_id;
582	                    let entry = CaseEntry {
583	                        case_id: case_id.clone(),
584	                        state: output.state.into(),
585	                        exit_code: Some(output.exit_code as i32),
586	                        run_dir: None,
587	                    };
588	                    state.cases.lock().await.insert(case_id.clone(), entry);
589	
590	                    // Fire notify_command (failure is logged and ignored — §10.3).
591	                    if let Some(argv) = &state.config.notify_command {
592	                        if !argv.is_empty() {
593	                            let event = serde_json::json!({
594	                                "event": "run_finished",
595	                                "case_id": case_id,
596	                            });
597	                            let _ = fire_notify(argv, event);
598	                        }
599	                    }
600	
601	                    serde_json::json!({
602	                        "case_id": case_id,
603	                        "state": output.state,
604	                        "exit_code": output.exit_code,
605	                    })
606	                }
607	                Err(e) => serde_json::json!({"error": e.to_string()}),
608	            }
609	        }
610	        Request::Status { case_id } => {
611	            let cases = state.cases.lock().await;
612	            match cases.get(&case_id) {
613	                Some(entry) => serde_json::to_value(entry).unwrap_or_default(),
614	                None => serde_json::json!({"error": "case not found"}),
615	            }
616	        }
617	        Request::Approve {
618	            case_id,
619	            approval_id,
620	            note,
621	        } => {
622	            let root = state.config.root.clone();
623	            let result = run_cli(
624	                &root,
625	                &[
626	                    "approve",
627	                    &case_id,
628	                    &approval_id,
629	                    "--root",
630	                    root.to_str().unwrap_or("."),
631	                ],
632	                note.as_deref(),
633	            )
634	            .await;
635	            match result {
636	                Ok(output) => {
637	                    let _ = state.permission_broker.resolve(&approval_id).await;
638	                    serde_json::json!({"ok": true, "output": output})
639	                }
640	                Err(e) => serde_json::json!({"error": e}),
641	            }
642	        }
643	        Request::Reject {
644	            case_id,
645	            approval_id,
646	            note,
647	        } => {
648	            let root = state.config.root.clone();
649	            let result = run_cli(
650	                &root,
651	                &[
652	                    "reject",
653	                    &case_id,
654	                    &approval_id,
655	                    "--root",
656	                    root.to_str().unwrap_or("."),
657	                ],
658	                note.as_deref(),
659	            )
660	            .await;
661	            match result {
662	                Ok(output) => {
663	                    let _ = state.permission_broker.resolve(&approval_id).await;
664	                    serde_json::json!({"ok": true, "output": output})
665	                }
666	                Err(e) => serde_json::json!({"error": e}),
667	            }
668	        }
669	        Request::AgentList => agent_probe::list(&state.config.agent),
670	        Request::AgentProbe {
671	            endpoint,
672	            prompt,
673	            model,
674	            policy,
675	            entity,
676	            process,
677	        } => {
678	            let permit = match state.semaphore.acquire().await {
679	                Ok(permit) => permit,
680	                Err(_) => return serde_json::json!({"error":"server semaphore unavailable"}),
681	            };
682	            let config = state.config.clone();
683	            let result = agent_probe::probe(
684	                &config,
685	                agent_probe::ProbeRequest {
686	                    endpoint_id: &endpoint,
687	                    prompt: &prompt,
688	                    model: model.as_deref(),
689	                    policy_path: &policy,
690	                    entity: &entity,
691	                    process: &process,
692	                },
693	                &agent_probe::EnvironmentCredentialResolver,
694	            )
695	            .await;
696	            drop(permit);
697	            match result {
698	                Ok(outcome) => serde_json::to_value(outcome).unwrap_or_else(
699	                    |_| serde_json::json!({"error":"probe response serialization failed"}),
700	                ),
701	                Err(error) => {
702	                    serde_json::json!({"error": error.to_string(), "error_class": error.class()})
703	                }
704	            }
705	        }
706	        Request::Delegate {
707	            endpoint,
708	            instruction,
709	            run_id: requested_run_id,
710	            model,
711	            max_turns,
712	            token_budget,
713	            criteria,
714	            policy,
715	            entity,
716	            process,
717	        } => {
718	            let delegation_run_id = match requested_run_id {
719	                Some(value) if valid_run_id(&value) => value,
720	                Some(_) => return serde_json::json!({"error":"invalid delegation run_id"}),
721	                None => match run_id() {
722	                    Ok(value) => value,
723	                    Err(error) => return serde_json::json!({"error": error.to_string()}),
724	                },
725	            };
726	            let delegation_case_id = match case_id() {
727	                Ok(value) => value,
728	                Err(error) => return serde_json::json!({"error": error.to_string()}),
729	            };
730	            let permit = match state.semaphore.acquire().await {
731	                Ok(permit) => permit,
732	                Err(_) => return serde_json::json!({"error":"server semaphore unavailable"}),
733	            };
734	            let cancel = Arc::new(AtomicBool::new(false));
735	            let requested = Arc::new(AtomicBool::new(false));
736	            let handle = DelegationHandle {
737	                case_id: delegation_case_id.clone(),
738	                cancel: Arc::clone(&cancel),
739	                requested,
740	            };
741	            if state
742	                .delegations
743	                .lock()
744	                .await
745	                .insert(delegation_run_id.clone(), handle)
746	                .is_some()
747	            {
748	                drop(permit);
749	                return serde_json::json!({"error":"delegation run_id already active"});
750	            }
751	            let config = state.config.clone();
752	            let run_for_execution = delegation_run_id.clone();
753	            let case_for_execution = delegation_case_id.clone();
754	            let cancel_for_execution = Arc::clone(&cancel);
755	            let result = delegation::execute_with_permission_broker(
756	                &config,
757	                delegation::DelegationRequest {
758	                    endpoint_id: &endpoint,
759	                    instruction: &instruction,
760	                    model: model.as_deref(),
761	                    max_turns,
762	                    token_budget,
763	                    criteria,
764	                    policy_path: &policy,
765	                    entity: &entity,
766	                    process: &process,
767	                    ..Default::default()
768	                },
769	                &agent_probe::EnvironmentCredentialResolver,
770	                delegation::DelegationEpisodeContext::standalone(
771	                    &case_for_execution,
772	                    &run_for_execution,
773	                ),
774	                move || cancel_for_execution.load(Ordering::SeqCst),
775	                Some(state.permission_broker.clone()),
776	            )
777	            .await;
778	            state.delegations.lock().await.remove(&delegation_run_id);
779	            drop(permit);
780	            match result {
781	                Ok(outcome) => serde_json::to_value(outcome).unwrap_or_else(
782	                    |_| serde_json::json!({"error":"delegation response serialization failed"}),
783	                ),
784	                Err(error) => {
785	                    serde_json::json!({"error": error.to_string(), "error_class": error.class()})
786	                }
787	            }
788	        }
789	        Request::CancelDelegation {
790	            run_id,
791	            policy,
792	            entity,
793	            process,
794	        } => cancel_delegation(state, &run_id, &policy, &entity, &process).await,
795	        Request::Ask {
796	            kind,
797	            subject,
798	            purpose,
799	            case,
800	            actor,
801	        } => {
802	            let Some(question_kind) = sea_forge_thoth::protocol::parse_question_kind(&kind) else {
803	                return serde_json::json!({"error": format!("unknown question kind: {kind}")});
804	            };
805	            let root = state.config.root.clone();
806	            let result = tokio::task::spawn_blocking(move || {
807	                sea_forge_thoth::service::ask(
808	                    &root,
809	                    &actor,
810	                    question_kind,
811	                    &subject,
812	                    &purpose,
813	                    case.as_deref(),
814	                )
815	            })
816	            .await
817	            .map_err(|e| ForgeError::Internal(format!("ask task panic: {e}")))
818	            .and_then(|result| result);
819	            match result {
820	                Ok(answer) => serde_json::to_value(answer).unwrap_or_else(
821	                    |_| serde_json::json!({"error": "answer serialization failed"}),
822	                ),
823	                Err(error) => {
824	                    serde_json::json!({"error": error.to_string(), "error_class": error.class()})
825	                }
826	            }
827	        }
828	    }
829	}
