844	async fn cancel_delegation(
845	    state: &Arc<ServerState>,
846	    run_id: &str,
847	    policy_path: &str,
848	    entity: &str,
849	    process: &str,
850	) -> serde_json::Value {
851	    let handle = match state.delegations.lock().await.get(run_id).cloned() {
852	        Some(handle) => handle,
853	        None => return serde_json::json!({"error":"delegation run not active"}),
854	    };
855	
856	    if handle
857	        .requested
858	        .compare_exchange(false, true, Ordering::SeqCst, Ordering::SeqCst)
859	        .is_err()
860	    {
861	        return serde_json::json!({
862	            "run_id": run_id,
863	            "state": "cancellation_already_requested"
864	        });
865	    }
866	
867	    let result = record_cancellation(
868	        &state.config,
869	        run_id,
870	        &handle.case_id,
871	        policy_path,
872	        entity,
873	        process,
874	    );
875	    match result {
876	        Ok(control_id) => {
877	            handle.cancel.store(true, Ordering::SeqCst);
878	            serde_json::json!({
879	                "run_id": run_id,
880	                "state": "cancellation_requested",
881	                "control_id": control_id
882	            })
883	        }
884	        Err(error) => {
885	            handle.requested.store(false, Ordering::SeqCst);
886	            serde_json::json!({"error": error.to_string(), "error_class": error.class()})
887	        }
888	    }
889	}
