891	fn record_cancellation(
892	    config: &ServerConfig,
893	    run_id: &str,
894	    case_id: &str,
895	    policy_path: &str,
896	    entity: &str,
897	    process: &str,
898	) -> Result<String, sea_forge_core::ForgeError> {
899	    let policy = agent_probe::resolve_policy_path(&config.root, policy_path);
900	    let bundle = AuthorityPolicyBundle::load(&policy)?;
901	    let engine = PolicyAuthorityEngine::new(bundle.clone())?;
