138	/// Hidden helper: run inside the jail to probe one TCP action, driven by env.
139	///
140	/// `SEA_FORGE_NET_PROBE` = `connect` | `bind`
141	/// `SEA_FORGE_NET_PORT`  = target port (connect) or port to bind (bind)
142	/// `SEA_FORGE_NET_OUT`   = absolute path to write the outcome to
143	///
144	/// Writes `ok` on success or `err:<message>` on failure. Exits non-zero on
145	/// failure so the sandbox layer also observes a non-clean completion.
146	#[test]
147	fn net_probe_helper() {
148	    let mode = match std::env::var("SEA_FORGE_NET_PROBE") {
149	        Ok(mode) => mode,
150	        Err(_) => return, // not running as the helper
151	    };
152	    let port: u16 = std::env::var("SEA_FORGE_NET_PORT")
153	        .expect("helper needs SEA_FORGE_NET_PORT")
154	        .parse()
155	        .expect("port must be u16");
156	    let out = std::env::var("SEA_FORGE_NET_OUT").expect("helper needs SEA_FORGE_NET_OUT");
157	
158	    let outcome = match mode.as_str() {
159	        "connect" => {
160	            use std::net::TcpStream;
161	            match TcpStream::connect(("127.0.0.1", port)) {
162	                Ok(_) => "ok".to_string(),
163	                Err(e) => format!("err:{e}"),
164	            }
165	        }
166	        "bind" => {
167	            use std::net::TcpListener;
168	            match TcpListener::bind(("127.0.0.1", port)) {
169	                Ok(_) => "ok".to_string(),
170	                Err(e) => format!("err:{e}"),
171	            }
172	        }
173	        other => format!("err:unknown-mode:{other}"),
174	    };
175	    let failed = outcome != "ok";
176	    fs::write(&out, &outcome).expect("helper failed to write outcome");
177	    // Exit non-zero on probe failure so the sandbox reports a non-clean run.
178	    if failed {
179	        std::process::exit(7);
180	    }
181	}
