fn find_run_field<'a>(records: &'a [sea_forge_ledger::LedgerEntry], kind: &str, run: &str) -> &'a Value {
    &records
        .iter()
        .find(|entry| entry.record_kind == kind && entry.payload["run_id"] == run)
        .unwrap_or_else(|| panic!("no {kind} record for run {run}"))
        .payload
}

